def copy_kind_to_releases(apps, schema_editor):
    """Releases before drafts existed were published right away with their
    project's kind."""
    Release = apps.get_model("packages", "Release")
    for release in Release.objects.select_related("project"):
        release.kind = release.project.kind
        release.save(update_fields=["kind"])


